const RecentActivity = ({ activities }) => {
  const getActivityIcon = (type) => {
    switch (type) {
      case 'project': return '🔄'
      case 'task': return '✅'
      case 'payment': return '💰'
      case 'user': return '👤'
      default: return '📝'
    }
  }

  const getActivityColor = (type) => {
    switch (type) {
      case 'project': return 'bg-blue-500'
      case 'task': return 'bg-green-500'
      case 'payment': return 'bg-yellow-500'
      case 'user': return 'bg-purple-500'
      default: return 'bg-gray-500'
    }
  }

  return (
    <div className="bg-white rounded-xl p-6 shadow-md border border-gray-100">
      <div className="flex justify-between items-center mb-6">
        <h3 className="text-xl font-bold text-gray-900">Activités Récentes</h3>
        <button className="text-blue-600 hover:text-blue-700 text-sm font-medium">
          Voir tout
        </button>
      </div>

      <div className="space-y-4">
        {activities.map(activity => (
          <div key={activity.id} className="flex items-start space-x-3 group">
            <div className={`flex-shrink-0 w-8 h-8 rounded-full ${getActivityColor(activity.type)} flex items-center justify-center text-white text-sm`}>
              {getActivityIcon(activity.type)}
            </div>
            <div className="flex-1 min-w-0">
              <p className="font-medium text-gray-900 group-hover:text-blue-600 transition duration-200">
                {activity.action}
              </p>
              <p className="text-sm text-gray-600 truncate">{activity.description}</p>
              <p className="text-xs text-gray-500 mt-1">{activity.time}</p>
            </div>
          </div>
        ))}
      </div>

      <button className="w-full mt-6 text-center text-blue-600 hover:text-blue-700 text-sm font-medium py-2 border border-gray-200 rounded-lg hover:bg-gray-50 transition duration-200">
        Charger plus d'activités
      </button>
    </div>
  )
}

export default RecentActivity
